/**
 * Client half of the CodeTrail DSH bundle.
 *
 * Registers one global sidebar panel entry (`codetrail`) and its main panel.
 * The panel talks to the package's Host half over the same-origin
 * /codetrail/ HTTP bridge; the workbench itself is the self-contained HTML
 * generated by the Rust core, shown in a frame so its graph renderer keeps
 * its full interactivity.
 */
window.__ModuleLoader__.load({
  id: 'codetrail-dsh',
  factory(require) {
    const React = require('react')
    const h = React.createElement
    const { useState, useEffect, useCallback } = React

    const API = '/codetrail/api'
    const HEADERS = { 'x-codetrail': '1' }

    const CSS = `
      .ctd-root { display: flex; flex-direction: column; height: 100%; min-height: 0;
        background: var(--dsw-alias-bg-base, #161616); color: var(--dsw-alias-label-primary, #e8e8e8);
        font-family: inherit; }
      .ctd-head { display: flex; align-items: center; gap: 12px; flex-wrap: wrap; padding: 10px 14px;
        border-bottom: 1px solid var(--dsw-alias-border-l1, #2c2c2c);
        background: var(--dsw-alias-bg-layer-1, #1b1b1b); }
      .ctd-brand { display: flex; align-items: center; gap: 9px; min-width: 0; }
      .ctd-mark { display: inline-flex; align-items: center; justify-content: center; width: 26px; height: 26px;
        border-radius: 8px; color: var(--dsw-alias-brand-primary, #7aa2f7); background: rgba(122, 162, 247, 0.14); }
      .ctd-title { font-size: 13px; font-weight: 600; line-height: 1.25; }
      .ctd-sub { font-size: 11px; color: var(--dsw-alias-label-secondary, #9a9a9a); line-height: 1.25; }
      .ctd-actions { margin-left: auto; display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
      .ctd-select { max-width: 300px; height: 28px; border-radius: 7px; padding: 0 8px; font-size: 12px;
        border: 1px solid var(--dsw-alias-border-l1, #333); background: var(--dsw-alias-bg-layer-2, #222);
        color: var(--dsw-alias-label-primary, #e8e8e8); }
      .ctd-btn { height: 28px; padding: 0 11px; border-radius: 7px; font-size: 12px; cursor: pointer;
        display: inline-flex; align-items: center; gap: 6px; white-space: nowrap;
        border: 1px solid var(--dsw-alias-border-l1, #333); background: var(--dsw-alias-bg-layer-2, #222);
        color: var(--dsw-alias-label-primary, #e8e8e8); }
      .ctd-btn:hover:not(:disabled) { border-color: var(--dsw-alias-border-l2, #555); }
      .ctd-btn:disabled { opacity: 0.55; cursor: default; }
      .ctd-btn--primary { background: var(--dsw-alias-brand-primary, #4a7fe0); border-color: transparent; color: #fff; }
      .ctd-btn--ghost { background: transparent; }
      .ctd-link { height: 28px; display: inline-flex; align-items: center; padding: 0 10px; border-radius: 7px;
        font-size: 12px; text-decoration: none; border: 1px solid transparent;
        color: var(--dsw-alias-label-secondary, #9a9a9a); }
      .ctd-link:hover { color: var(--dsw-alias-label-primary, #e8e8e8); border-color: var(--dsw-alias-border-l1, #333); }
      .ctd-status { padding: 6px 14px; font-size: 12px; border-bottom: 1px solid var(--dsw-alias-border-l1, #2c2c2c);
        color: var(--dsw-alias-label-secondary, #9a9a9a); }
      .ctd-error { padding: 8px 14px; font-size: 12px; white-space: pre-wrap; border-bottom: 1px solid var(--dsw-alias-border-l1, #2c2c2c);
        color: var(--dsw-alias-state-error-primary, #e5484d); }
      .ctd-body { position: relative; flex: 1; min-height: 0; display: flex; }
      .ctd-frame { flex: 1; width: 100%; height: 100%; border: 0; display: block; background: #141414; }
      .ctd-empty { flex: 1; display: flex; flex-direction: column; align-items: center; justify-content: center;
        gap: 10px; padding: 32px; text-align: center; }
      .ctd-empty-mark { color: var(--dsw-alias-label-secondary, #888); opacity: 0.7; }
      .ctd-empty-title { font-size: 14px; font-weight: 600; }
      .ctd-empty-text { max-width: 440px; font-size: 12px; line-height: 1.65;
        color: var(--dsw-alias-label-secondary, #9a9a9a); }
      .ctd-meta { display: flex; gap: 14px; font-size: 11px; color: var(--dsw-alias-label-secondary, #9a9a9a); }
    `

    function TrailMark(props) {
      const size = (props && props.size) || 16
      return h('svg', {
        width: size, height: size, viewBox: '0 0 24 24', fill: 'none',
        stroke: 'currentColor', strokeWidth: 1.7, strokeLinecap: 'round',
        strokeLinejoin: 'round', 'aria-hidden': true, style: { display: 'block' },
      },
        h('path', { d: 'M6 18.5 10 6.5' }),
        h('path', { d: 'M10 6.5 16.5 13' }),
        h('path', { d: 'M16.5 13 20.5 7' }),
        h('circle', { cx: 6, cy: 18.5, r: 1.9 }),
        h('circle', { cx: 10, cy: 6.5, r: 1.9 }),
        h('circle', { cx: 16.5, cy: 13, r: 1.9 }),
        h('circle', { cx: 20.5, cy: 7, r: 1.9 })
      )
    }

    function PanelIcon(props) {
      const size = (props && props.size) || 16
      return h(TrailMark, { size })
    }

    function currentTheme() {
      try {
        return document.body && document.body.hasAttribute('data-ds-dark-theme') ? 'dark' : 'light'
      } catch {
        return 'dark'
      }
    }

    function formatTime(iso) {
      try {
        return new Date(iso).toLocaleString()
      } catch {
        return String(iso || '')
      }
    }

    function readLocaleId(locale) {
      try {
        const snapshot = locale && locale.getLocale()
        if (!snapshot) return ''
        return String(snapshot.locale || snapshot.language || snapshot.id || '')
      } catch {
        return ''
      }
    }

    function createPanel(ctx, tr) {
      const uiWorkspace = ctx.get('uiWorkspace')

      return function CodeTrailPanel() {
        const [scans, setScans] = useState([])
        const [selectedId, setSelectedId] = useState(null)
        const [busy, setBusy] = useState('')
        const [error, setError] = useState('')
        const [theme, setTheme] = useState(currentTheme)

        const load = useCallback(async () => {
          try {
            const response = await fetch(`${API}/state`, { headers: HEADERS, cache: 'no-store' })
            const data = await response.json().catch(() => ({}))
            if (!response.ok || !data.ok) throw new Error((data && data.error) || `HTTP ${response.status}`)
            const list = Array.isArray(data.scans) ? data.scans : []
            setScans(list)
            setError('')
            setSelectedId(previous => {
              if (previous && list.some(item => item.id === previous)) return previous
              return list.length > 0 ? list[0].id : null
            })
          } catch (loadError) {
            setError(String(loadError && loadError.message ? loadError.message : loadError))
          }
        }, [])

        useEffect(() => {
          load()
        }, [load])

        useEffect(() => {
          const body = document.body
          if (!body || typeof MutationObserver === 'undefined') return undefined
          const observer = new MutationObserver(() => setTheme(currentTheme()))
          observer.observe(body, { attributes: true, attributeFilter: ['data-ds-dark-theme'] })
          return () => observer.disconnect()
        }, [])

        const runAction = useCallback(async type => {
          setError('')
          if (!uiWorkspace || typeof uiWorkspace.pickDirectory !== 'function') {
            setError(tr('目录选择服务不可用。', 'The directory picker is unavailable.'))
            return
          }
          let picked
          try {
            picked = await uiWorkspace.pickDirectory()
          } catch (pickError) {
            setError(String(pickError && pickError.message ? pickError.message : pickError))
            return
          }
          if (!picked) return
          setBusy(type === 'review' ? tr('正在审查 Git 修改…', 'Reviewing Git changes…') : tr('正在扫描仓库…', 'Scanning repository…'))
          try {
            const response = await fetch(`${API}/scan`, {
              method: 'POST',
              headers: { ...HEADERS, 'content-type': 'application/json' },
              body: JSON.stringify({ path: picked, type }),
            })
            const data = await response.json().catch(() => ({}))
            if (!response.ok || !data.ok) throw new Error((data && data.error) || `HTTP ${response.status}`)
            await load()
            if (data.record && data.record.id) setSelectedId(data.record.id)
          } catch (runError) {
            setError(String(runError && runError.message ? runError.message : runError))
          } finally {
            setBusy('')
          }
        }, [load, uiWorkspace, tr])

        const selected = scans.find(item => item.id === selectedId) || null
        const frameSrc = selected ? `/codetrail/view/${encodeURIComponent(selected.id)}?theme=${theme}` : ''
        const disabled = Boolean(busy)

        const summary = selected && selected.summary ? selected.summary : {}

        return h('div', { className: 'ctd-root' },
          h('header', { className: 'ctd-head' },
            h('div', { className: 'ctd-brand' },
              h('span', { className: 'ctd-mark' }, h(TrailMark, { size: 17 })),
              h('div', null,
                h('div', { className: 'ctd-title' }, 'CodeTrail'),
                h('div', { className: 'ctd-sub' }, tr('Rust 静态代码图 · 仅本地分析', 'Rust static code graph · local only'))
              )
            ),
            h('div', { className: 'ctd-actions' },
              scans.length > 0
                ? h('select', {
                    className: 'ctd-select',
                    value: selectedId || '',
                    onChange: event => setSelectedId(event.target.value),
                    'aria-label': tr('选择扫描记录', 'Choose a scan'),
                  }, scans.map(item => h('option', { key: item.id, value: item.id },
                    `${item.type === 'review' ? tr('修改影响', 'Review') : tr('架构导览', 'Architecture')} · ${item.repoName} · ${formatTime(item.createdAt)}`)))
                : null,
              h('button', {
                type: 'button',
                className: 'ctd-btn ctd-btn--primary',
                disabled,
                onClick: () => runAction('scan'),
              }, tr('扫描目录', 'Scan directory')),
              h('button', {
                type: 'button',
                className: 'ctd-btn',
                disabled,
                onClick: () => runAction('review'),
              }, tr('审查修改', 'Review changes')),
              h('button', {
                type: 'button',
                className: 'ctd-btn ctd-btn--ghost',
                disabled,
                onClick: load,
              }, tr('刷新', 'Refresh')),
              selected
                ? h('a', {
                    className: 'ctd-link',
                    href: frameSrc,
                    target: '_blank',
                    rel: 'noreferrer',
                  }, tr('新窗口打开', 'Open in new window'))
                : null
            )
          ),
          busy ? h('div', { className: 'ctd-status' }, busy) : null,
          error ? h('div', { className: 'ctd-error' }, error) : null,
          selected
            ? h('div', { className: 'ctd-meta', style: { padding: '6px 14px', borderBottom: '1px solid var(--dsw-alias-border-l1, #2c2c2c)' } },
                h('span', null, `repo: ${selected.repo}`),
                h('span', null, `${tr('函数', 'functions')} ${summary.functions ?? '?'}`),
                h('span', null, `${tr('边', 'edges')} ${summary.edges ?? '?'}`),
                h('span', null, `${tr('诊断', 'diagnostics')} ${summary.diagnostics ?? '?'}`)
              )
            : null,
          h('div', { className: 'ctd-body' },
            selected
              ? h('iframe', {
                  key: `${selected.id}:${theme}`,
                  className: 'ctd-frame',
                  title: 'CodeTrail workbench',
                  src: frameSrc,
                })
              : h('div', { className: 'ctd-empty' },
                  h('div', { className: 'ctd-empty-mark' }, h(TrailMark, { size: 56 })),
                  h('div', { className: 'ctd-empty-title' }, tr('还没有扫描记录', 'No scans yet')),
                  h('p', { className: 'ctd-empty-text' },
                    tr(
                      '点击「扫描目录」选择要分析的仓库；也可以直接在对话中让我调用 code_trail_scan / code_trail_review。扫描结果会保存在本机 CodeTrail 数据目录，并出现在这里。',
                      'Choose a repository with “Scan directory”, or ask me in the conversation to call code_trail_scan / code_trail_review. Results are stored locally and listed here.'
                    ))
                )
          )
        )
      }
    }

    return {
      inject: ['slots', 'uiWorkspace', 'theme', 'locale'],
      apply(ctx) {
        const locale = ctx.get('locale')
        const localeId = readLocaleId(locale).toLowerCase()
        const isEnglish = localeId.startsWith('en')
        const tr = (zh, en) => (isEnglish ? en : zh)

        ctx.effect(() => {
          const style = document.createElement('style')
          style.setAttribute('data-codetrail-dsh', '')
          style.textContent = CSS
          document.head.appendChild(style)
          return () => style.remove()
        }, 'codetrail-dsh client styles')

        const Panel = createPanel(ctx, tr)

        ctx.slots.inject('sidebar.panellist', () => ctx.slots.register({
          name: 'sidebar.panellist',
          id: 'codetrail',
          order: 30,
          label: () => tr('CodeTrail 架构导览', 'CodeTrail'),
        }, PanelIcon))

        ctx.slots.inject('main', () => ctx.slots.register({
          name: 'main',
          key: 'codetrail',
        }, Panel))
      },
    }
  },
})
